- [ ] **Step 3: Implement browser host types**

Create `projects/synth/browser/cpp/BrowserHostTypes.hpp`:

```cpp
#pragma once

#include "synth/CircularQueue.hpp"

#include <atomic>
#include <cstdint>
#include <cstring>

namespace synth_browser {

inline constexpr bool kBrowserHostUsesJuce = false;
inline constexpr int kMaxNodeIdBytes = 96;
inline constexpr int kMaxActionNameBytes = 96;
inline constexpr int kMaxActionValueBytes = 256;
inline constexpr int kDefaultUiFrameHz = 60;

enum class BrowserStatusCode : std::int32_t {
    Ready = 0,
    MissingSharedArrayBuffer = 1,
    MissingCrossOriginIsolation = 2,
    AudioInputUnsupported = 3,
    NotInitialized = 4,
    AudioFailed = 5,
    StorageSyncPending = 6,
    StorageFailed = 7,
    MidiUnavailable = 8
};

struct BrowserStatus {
    BrowserStatusCode code = BrowserStatusCode::NotInitialized;
    std::int32_t detail = 0;
};

enum class MessageKind : std::int32_t {
    UiAction = 1,
    MidiInput = 2,
    AudioStatus = 3,
    FrameDirty = 4,
    MidiOutput = 5,
    StorageRequest = 6,
    LogRecord = 7
};

struct ActionMessage {
    MessageKind kind = MessageKind::UiAction;
    char nodeId[kMaxNodeIdBytes]{};
    char actionName[kMaxActionNameBytes]{};
    char value[kMaxActionValueBytes]{};
};

struct MidiMessage {
    MessageKind kind = MessageKind::MidiInput;
    std::uint8_t bytes[3]{};
    std::uint8_t size = 0;
    double timestampMs = 0.0;
};

template <typename T, std::size_t N>
class SpscQueue {
public:
    bool Push(const T& value) {
        if (!queue_.Push(value)) {
            dropped_.fetch_add(1, std::memory_order_relaxed);
            return false;
        }
        return true;
    }

    bool Pop(T& value) {
        return queue_.Pop(value);
    }

    std::size_t Size() const {
        return queue_.Size();
    }

    std::uint64_t DroppedCount() const {
        return dropped_.load(std::memory_order_relaxed);
    }

private:
    synth::CircularQueue<T, N> queue_;
    std::atomic<std::uint64_t> dropped_{0};
};

inline BrowserStatus SharedMemoryDiagnostics(bool hasSharedArrayBuffer, bool crossOriginIsolated) {
    if (!hasSharedArrayBuffer) {
        return BrowserStatus{BrowserStatusCode::MissingSharedArrayBuffer, 0};
    }
    if (!crossOriginIsolated) {
        return BrowserStatus{BrowserStatusCode::MissingCrossOriginIsolation, 0};
    }
    return BrowserStatus{BrowserStatusCode::Ready, 0};
}

inline BrowserStatus AudioInputSupportStatus(int inputChannels) {
    if (inputChannels > 0) {
        return BrowserStatus{BrowserStatusCode::AudioInputUnsupported, inputChannels};
    }
    return BrowserStatus{BrowserStatusCode::Ready, 0};
}

inline void CopyCString(char* destination, int capacity, const char* source) {
    if (capacity <= 0) {
        return;
    }
    if (source == nullptr) {
        destination[0] = '\0';
        return;
    }
    std::strncpy(destination, source, static_cast<std::size_t>(capacity - 1));
    destination[capacity - 1] = '\0';
}

}  // namespace synth_browser
```

- [ ] **Step 4: Implement a compiling C ABI shell**

Create `projects/synth/browser/cpp/BrowserMiniAppHost.cpp` with a minimal engine-backed host:

```cpp
#include "BrowserHostTypes.hpp"

#include "MiniAppCore.hpp"
#include "synth/Engine.hpp"

#include <cstdint>
#include <memory>

namespace {

struct HostState {
    std::unique_ptr<synth::Engine<MiniAppCore>> engine;
    synth_browser::BrowserStatus status;
    double sampleRate = 0.0;
    int blockSize = 0;
};

HostState& State() {
    static HostState state;
    return state;
}

}  // namespace

extern "C" int sheath_browser_create(int, int) {
    auto& state = State();
    state.engine = std::make_unique<synth::Engine<MiniAppCore>>([] { return std::uint64_t{0}; });
    state.engine->Initialize();
    state.status = synth_browser::BrowserStatus{synth_browser::BrowserStatusCode::Ready, 0};
    return 0;
}

extern "C" int sheath_browser_prepare(double sampleRate, int blockSize) {
    auto& state = State();
    if (!state.engine) {
        state.status = synth_browser::BrowserStatus{synth_browser::BrowserStatusCode::NotInitialized, 0};
        return -1;
    }
    state.sampleRate = sampleRate;
    state.blockSize = blockSize;
    state.engine->Prepare(sampleRate, blockSize);
    return 0;
}

extern "C" int sheath_browser_process(float**, int, int frames) {
    auto& state = State();
    if (!state.engine || frames <= 0) {
        return -1;
    }
    return 0;
}

extern "C" int sheath_browser_message_tick(std::uint64_t) {
    auto& state = State();
    if (!state.engine) {
        return -1;
    }
    state.engine->MessageThreadTick();
    return 0;
}

extern "C" int sheath_browser_dispatch_action(const char*, const char*, const char*) {
    return 0;
}

extern "C" int sheath_browser_audio_input_supported() {
    return static_cast<int>(synth_browser::AudioInputSupportStatus(MiniAppCore::Config().numAudioInputs).code);
}

extern "C" const synth_browser::BrowserStatus* sheath_browser_status() {
    return &State().status;
}

extern "C" void sheath_browser_shutdown() {
    State() = HostState{};
}
```

If `MiniAppCore::Config()` is not the correct static access point, use the app type that already satisfies `synth::SynthApplicationCore` in `projects/synth/apps/miniapp`.

