- [ ] **Step 3: Implement bounded frame serialization**

Create `projects/synth/browser/cpp/BrowserFrameSerializer.hpp` with fixed-size vectors and explicit truncation flags:

```cpp
#pragma once

#include "BrowserHostTypes.hpp"
#include "synth/PortableUI.hpp"

#include <cstdint>
#include <string>
#include <vector>

namespace synth_browser {

inline constexpr std::size_t kMaxFrameNodes = 512;
inline constexpr std::size_t kMaxFrameDrawCommands = 4096;

enum class FrameNodeKind : std::int32_t {
    Root,
    Row,
    Section,
    ScrollArea,
    Label,
    Button,
    Toggle,
    Slider,
    ComboBox,
    TextField,
    StatusText,
    Draw
};

struct FrameHeader {
    std::uint32_t version = 0;
    std::uint32_t dirty = 0;
    std::uint32_t truncated = 0;
    std::uint32_t nodeCount = 0;
    std::uint32_t drawCommandCount = 0;
};

struct FrameNode {
    std::string id;
    FrameNodeKind kind = FrameNodeKind::Label;
    synth::ui::Bounds bounds{};
    std::string label;
    std::string text;
    std::string actionName;
    std::string actionValue;
    float value = 0.0f;
    float minValue = 0.0f;
    float maxValue = 1.0f;
    bool checked = false;
    bool enabled = true;
};

struct FrameDrawCommand {
    std::string ownerNodeId;
    synth::ui::DrawCommand command;
};

struct SerializedFrame {
    FrameHeader header;
    std::vector<FrameNode> nodes;
    std::vector<FrameDrawCommand> drawCommands;
};

inline FrameNodeKind ConvertNodeKind(synth::ui::NodeKind kind) {
    switch (kind) {
        case synth::ui::NodeKind::Root: return FrameNodeKind::Root;
        case synth::ui::NodeKind::Row: return FrameNodeKind::Row;
        case synth::ui::NodeKind::Section: return FrameNodeKind::Section;
        case synth::ui::NodeKind::ScrollArea: return FrameNodeKind::ScrollArea;
        case synth::ui::NodeKind::Label: return FrameNodeKind::Label;
        case synth::ui::NodeKind::Button: return FrameNodeKind::Button;
        case synth::ui::NodeKind::Toggle: return FrameNodeKind::Toggle;
        case synth::ui::NodeKind::Slider: return FrameNodeKind::Slider;
        case synth::ui::NodeKind::ComboBox: return FrameNodeKind::ComboBox;
        case synth::ui::NodeKind::TextField: return FrameNodeKind::TextField;
        case synth::ui::NodeKind::StatusText: return FrameNodeKind::StatusText;
        case synth::ui::NodeKind::Draw: return FrameNodeKind::Draw;
    }
    return FrameNodeKind::Label;
}

inline SerializedFrame SerializeFrame(const synth::ui::NodeTree& tree, std::uint32_t version, bool dirty) {
    SerializedFrame frame;
    frame.header.version = version;
    frame.header.dirty = dirty ? 1u : 0u;
    frame.nodes.reserve(std::min(tree.nodes.size(), kMaxFrameNodes));
    for (const auto& node : tree.nodes) {
        if (frame.nodes.size() == kMaxFrameNodes) {
            frame.header.truncated = 1;
            break;
        }
        FrameNode out;
        out.id = node.id.value;
        out.kind = ConvertNodeKind(node.kind);
        out.bounds = node.bounds;
        out.label = node.label;
        out.text = node.text;
        out.value = node.value;
        out.minValue = node.minValue;
        out.maxValue = node.maxValue;
        out.checked = node.checked;
        out.enabled = node.enabled;
        if (node.action.has_value()) {
            out.actionName = node.action->name;
            out.actionValue = node.action->value;
        }
        frame.nodes.push_back(std::move(out));
        for (const auto& command : node.drawCommands) {
            if (frame.drawCommands.size() == kMaxFrameDrawCommands) {
                frame.header.truncated = 1;
                continue;
            }
            frame.drawCommands.push_back(FrameDrawCommand{node.id.value, command});
        }
    }
    frame.header.nodeCount = static_cast<std::uint32_t>(frame.nodes.size());
    frame.header.drawCommandCount = static_cast<std::uint32_t>(frame.drawCommands.size());
    return frame;
}

}  // namespace synth_browser
```

