- [ ] **Step 3: Implement runtime helpers**

Create `projects/synth/browser/js/runtime.js`:

```js
export const BrowserRuntimeStatus = Object.freeze({
  ready: "ready",
  missingSharedArrayBuffer: "missing-shared-array-buffer",
  missingCrossOriginIsolation: "missing-cross-origin-isolation",
  audioSuspended: "audio-suspended",
  audioRunning: "audio-running",
  audioFailed: "audio-failed",
});

export function assertSharedMemorySupport(scope = globalThis) {
  if (typeof scope.SharedArrayBuffer !== "function") {
    return { code: BrowserRuntimeStatus.missingSharedArrayBuffer };
  }
  if (scope.crossOriginIsolated !== true) {
    return { code: BrowserRuntimeStatus.missingCrossOriginIsolation };
  }
  return { code: BrowserRuntimeStatus.ready };
}

export async function loadCompiledModule(url, fetchImpl = fetch) {
  const response = await fetchImpl(url);
  if (!response.ok) {
    throw new Error(`Unable to fetch Wasm module: ${response.status}`);
  }
  const bytes = await response.arrayBuffer();
  return WebAssembly.compile(bytes);
}

export function buildWorkletInitMessage({ module, memory, exports, sampleRate, quantumSize = 128 }) {
  return { type: "init", module, memory, exports, sampleRate, quantumSize };
}

export class BrowserRuntime {
  constructor({ wasmModule, wasmExports, messageTickHz = 60 }) {
    this.wasmModule = wasmModule;
    this.wasmExports = wasmExports;
    this.messageTickMs = 1000 / messageTickHz;
    this.lastTickMs = 0;
    this.status = BrowserRuntimeStatus.ready;
  }

  tickMessageThread(nowMs) {
    if (nowMs - this.lastTickMs < this.messageTickMs) {
      return false;
    }
    this.lastTickMs = nowMs;
    if (this.wasmExports?.sheath_browser_message_tick) {
      this.wasmExports.sheath_browser_message_tick(BigInt(Math.trunc(nowMs)));
    }
    return true;
  }
}
