import http from "node:http";
import { createReadStream, existsSync } from "node:fs";
import { extname, join, normalize } from "node:path";
import { fileURLToPath } from "node:url";

const root = normalize(join(fileURLToPath(new URL("..", import.meta.url)), "public"));

export function headersForPath(pathname) {
  const headers = {
    "Cross-Origin-Opener-Policy": "same-origin",
    "Cross-Origin-Embedder-Policy": "require-corp",
    "Permissions-Policy": "midi=*",
  };
  if (pathname.endsWith(".wasm")) {
    headers["Content-Type"] = "application/wasm";
  } else if (pathname.endsWith(".js") || pathname.endsWith(".mjs")) {
    headers["Content-Type"] = "text/javascript; charset=utf-8";
  } else if (pathname.endsWith(".html") || pathname === "/") {
    headers["Content-Type"] = "text/html; charset=utf-8";
  }
  return headers;
}

export function createStaticPreviewServer({ port = 8788 } = {}) {
  return http.createServer((request, response) => {
    const url = new URL(request.url, `http://127.0.0.1:${port}`);
    const pathname = url.pathname === "/" ? "/index.html" : url.pathname;
    const absolute = normalize(join(root, pathname));
    if (!absolute.startsWith(root) || !existsSync(absolute)) {
      response.writeHead(404, headersForPath(pathname));
      response.end("not found");
      return;
    }
    response.writeHead(200, headersForPath(pathname));
    createReadStream(absolute).pipe(response);
  });
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const port = Number(process.env.PORT || 8788);
  createStaticPreviewServer({ port }).listen(port, "127.0.0.1", () => {
    console.log(`browser synth preview: http://127.0.0.1:${port}`);
  });
}
