class SheathSynthProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    this.ready = false;
    this.exports = null;
    this.port.onmessage = (event) => {
      if (event.data?.type === "init") {
        this.exports = event.data.exports ?? null;
        this.ready = true;
        this.port.postMessage({ type: "status", status: "worklet-ready" });
      }
    };
  }

  process(inputs, outputs) {
    const output = outputs[0] ?? [];
    if (!this.ready || !this.exports?.sheath_browser_process) {
      for (const channel of output) channel.fill(0);
      return true;
    }
    this.exports.sheath_browser_process(0, output.length, output[0]?.length ?? 128);
    return true;
  }
}

registerProcessor("sheath-synth", SheathSynthProcessor);
