```js
export class BrowserUiRenderer {
  constructor({ root, canvas, document = globalThis.document, dispatchAction }) {
    this.root = root;
    this.canvas = canvas;
    this.document = document;
    this.dispatchAction = dispatchAction;
    this.lastVersion = -1;
  }

  renderFrame(frame) {
    if (!frame?.header?.dirty || frame.header.version === this.lastVersion) {
      return false;
    }
    this.lastVersion = frame.header.version;
    const elements = frame.nodes.filter((node) => node.kind !== "Draw").map((node) => this.createControl(node));
    this.root.replaceChildren(...elements);
    if (this.canvas) {
      this.renderCanvas(frame.drawCommands ?? []);
    }
    return true;
  }

  createControl(node) {
    const kind = node.kind;
    const tag = kind === "Button" ? "button" : kind === "Slider" ? "input" : kind === "TextField" ? "input" : "div";
    const el = this.document.createElement(tag);
    el.dataset.nodeId = node.id;
    el.textContent = node.label || node.text || "";
    if (kind === "Slider") {
      el.type = "range";
      el.min = String(node.minValue ?? 0);
      el.max = String(node.maxValue ?? 1);
      el.value = String(node.value ?? 0);
      el.addEventListener("input", () => this.dispatchAction(node.id, node.actionName, String(el.value)));
    } else if (kind === "Button") {
      el.addEventListener("click", () => this.dispatchAction(node.id, node.actionName, node.actionValue ?? ""));
    } else if (kind === "Toggle") {
      el.addEventListener("change", () => this.dispatchAction(node.id, node.actionName, el.checked ? "1" : "0"));
    }
    return el;
  }

  renderCanvas(commands) {
    const context = this.canvas.getContext("2d");
    if (!context) return;
    for (const item of commands) {
      const command = item.command ?? item;
      if (command.kind === "Line") {
        context.beginPath();
        context.moveTo(command.from.x, command.from.y);
        context.lineTo(command.to.x, command.to.y);
        context.stroke();
      } else if (command.kind === "Fill") {
        context.fillRect(command.bounds?.x ?? 0, command.bounds?.y ?? 0, command.bounds?.width ?? this.canvas.width, command.bounds?.height ?? this.canvas.height);
      }
    }
  }
}
```

