```js
export const BrowserMidiStatus = Object.freeze({
  available: "available",
  unavailable: "unavailable",
});

export function mapMidiPorts(inputs, outputs) {
  const mapPort = (port) => ({
    id: port.id,
    name: port.name ?? "",
    manufacturer: port.manufacturer ?? "",
    type: port.type,
    state: port.state,
  });
  return {
    inputs: Array.from(inputs.values(), mapPort),
    outputs: Array.from(outputs.values(), mapPort),
  };
}

export async function requestBrowserMidi({ navigator = globalThis.navigator } = {}) {
  if (!navigator?.requestMIDIAccess) {
    return { status: BrowserMidiStatus.unavailable, reason: "Web MIDI is unavailable" };
  }
  try {
    const access = await navigator.requestMIDIAccess({ sysex: true });
    return { status: BrowserMidiStatus.available, access, ports: mapMidiPorts(access.inputs, access.outputs) };
  } catch (error) {
    return { status: BrowserMidiStatus.unavailable, reason: `${error.name ?? "Error"}: ${error.message ?? error}` };
  }
}

export class BrowserMidiAdapter {
  constructor({ access, enqueueMidiInput, sendMidiOutput }) {
    this.access = access;
    this.enqueueMidiInput = enqueueMidiInput;
    this.sendMidiOutput = sendMidiOutput;
  }

  attachInputs() {
    for (const input of this.access.inputs.values()) {
      input.onmidimessage = (event) => this.enqueueMidiInput(Array.from(event.data), event.timeStamp);
    }
  }

  send(portId, bytes) {
    const output = this.access.outputs.get(portId);
    if (output) {
      output.send(bytes);
      return true;
    }
    return false;
  }
}
```

