export const BrowserStorageStatus = Object.freeze({
  pending: "pending",
  ready: "ready",
  failed: "failed",
});

export function mountBrowserStorage(Module, mountPoint = "/sheath") {
  Module.FS.mkdir(mountPoint);
  Module.FS.mount(Module.IDBFS, {}, mountPoint);
}

export function syncBrowserStorage(Module, populate) {
  return new Promise((resolve, reject) => {
    Module.syncfs(populate, (error) => {
      if (error) reject(error);
      else resolve();
    });
  });
}

export function appendBrowserLog(Module, mountPoint, message, now = new Date()) {
  const stamp = now.toISOString().replaceAll(":", "-");
  Module.FS.writeFile(`${mountPoint}/logs/browser-${stamp}.log`, `${message}\n`);
}
